SELECT c.id, c.name, c.age, t.pct_open, t.savings_balance FROM customers c INNER JOIN (SELECT customer_id, ROUND((100 * SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_open, SUM(CASE WHEN account_type = 'SAVINGS' THEN balance ELSE 0 END) AS savings_balance FROM accounts WHERE balance >= 23000 GROUP BY customer_id) t ON c.id = t.customer_id WHERE t.pct_open > 53;
